with exploded as (select id, plan, effective_from, tier_value from price_tiers lateral view outer explode(discounts) t as tier_value), filtered as (select *, date_trunc('WEEK', effective_from) as effective_from_period from exploded where effective_from > date '2024-05-11' and plan = 'starter'), metrics as (select tier_value, effective_from_period, max(tier_value) over (order by cast(effective_from_period as bigint) range between 7776000 preceding and current row) as tier_value_max_90d, percent_rank() over (partition by date_trunc('month', effective_from), plan order by tier_value desc) as tier_value_percent_rank, sum(tier_value) over (partition by plan) as plan_sum_tier_value from filtered where effective_from between '2023-07-01' and '2024-04-01'), cleaned as (select *, date_trunc('WEEK', effective_from_period) as effective_from_period_period from metrics where to_date(effective_from_period) >= '2024-02-01'), metrics_price_tiers as (select tier_value, tier_value_max_90d, tier_value_percent_rank, plan_sum_tier_value, count(plan_sum_tier_value) over (order by cast(effective_from_period as bigint) range between 2592000 preceding and current row) as plan_sum_tier_value_count_30d, stddev_samp(tier_value_percent_rank) over (partition by year(effective_from_period)) as effective_from_period_year_stddev_samp_tier_value_percent_rank from cleaned) select tier_value_max_90d, tier_value_percent_rank, plan_sum_tier_value, plan_sum_tier_value_count_30d from metrics_price_tiers order by plan_sum_tier_value, plan_sum_tier_value_count_30d;
